    height: 80vh;
    background: linear-gradient(rgba(0,0,0,0.3), rgba(0,0,0,0.3)), url('https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=1600&q=80');
    background-size: cover;
    background-position: center;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--white);
    text-align: center;
    padding: 0 1rem;
}

.hero-content h1 {
    font-size: clamp(2.5rem, 8vw, 4.5rem);
    margin-bottom: 1rem;
    line-height: 1.1;
}

.cta-button {
    display: inline-block;
    padding: 1rem 2.5rem;
    background: var(--white);
    color: var(--primary);
    text-decoration: none;
    font-weight: 600;
    transition: transform 0.2s, background 0.2s;
}

.cta-button:hover {
    transform: translateY(-2px);
    background: var(--secondary);
}

section {
    padding: 5rem 5%;
}

.section-title {
    font-size: 2rem;
    margin-bottom: 3rem;
    text-align: center;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
}

.product-card {
    border: 1px solid var(--secondary);
    padding: 1rem;
    transition: box-shadow 0.3s;
}

.product-card:hover {
    box-shadow: 0 10px 20px rgba(0,0,0,0.05);
}

.product-image {
    width: 100%;
    aspect-ratio: 1/1;
    object-fit: cover;
    background: #f9f9f9;
    margin-bottom: 1rem;
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.price {
    font-weight: 700;
    color: var(--primary);
}

.old-price {
    text-decoration: line-through;
    color: #888;
    margin-right: 0.5rem;
    font-size: 0.9rem;
}

.deal-badge {
    background: var(--accent);
    color: var(--white);
    padding: 0.2rem 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    margin-bottom: 0.5rem;
    display: inline-block;
}

.editorial {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: 4rem;
    background: var(--secondary);
}

@media (max-width: 768px) {
    .editorial {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
}

.editorial-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

footer {
    background: var(--primary);
    color: var(--white);
    padding: 4rem 5%;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 3rem;
}

footer h4 {
    margin-bottom: 1.5rem;
}

footer ul {
    list-style: none;
}

footer li {
    margin-bottom: 0.8rem;
}

footer a {
    color: #ccc;
    text-decoration: none;
}

footer a:hover {
    color: var(--white);
}

/* Focus styles for accessibility */
a:focus-visible, button:focus-visible {
    outline: 2px solid var(--focus);
    outline-offset: 4px;
}
